value:healthBody:
"
  if (!h || !STREAM_WARN_CARDS[h.collector]) return;
  var card = $(STREAM_WARN_CARDS[h.collector]);
  var warn = $(STREAM_WARN_CARDS[h.collector] + 'Warn');
  if (!card || !warn) return;
  if (h.degraded) {
    warn.textContent = '⚠ Data incomplete — stream restarted '
      + h.restarts + ' times without recovering';
    card.classList.add('is-degraded');
  } else {
    warn.textContent = '';
    card.classList.remove('is-degraded');
  }
"

value:wanSrc:
"function renderWanStatus(s){
  wanStatusBadge.className='wan-badge';
  if(s.disabled){wanStatusBadge.className+=' wan-disabled';wanStatusBadge.textContent=(s.ifName||'?')+' · disabled';}
  else if(s.running){wanStatusBadge.className+=' wan-up';wanStatusBadge.textContent=(s.ifName||'?')+' · up';}
  else{wanStatusBadge.className+=' wan-down';wanStatusBadge.textContent=(s.ifName||'?')+' · down';}
}"
